// The acceptance-stream-a fixture's page: its sidebar app button's component, which the window mounts in a frame of the
// plugin's own layer as soon as it runs (§5.4 "Streams"). It accepts "down" (its host half writes generated bytes of seed 1
// to it: it counts them and checksums them, FNV-1a, and says so through `host.call("pageReport")`), and on its host
// half's "go-up" event opens "up" to its host half and writes `bytes` of seed 2 (it reports what it wrote). The host half
// counts what it read: the run compares the two ends.
import { useEffect, useState } from "react";
import { usePluginApi } from "@waifucave/moss-plugin-sdk/ui";

/** Bytes `from`..`from + n` of the stream of `seed`: the same function in every half. */
function gen(seed: number, from: number, n: number): Uint8Array {
  const b = new Uint8Array(n);
  for (let i = 0; i < n; i++) {
    const k = from + i;
    b[i] = (k * 131 + (k >>> 8) * 7 + seed * 13) & 255;
  }
  return b;
}
const fnv = (h: number, bytes: Uint8Array): number => {
  for (let i = 0; i < bytes.length; i++) h = Math.imul(h ^ bytes[i]!, 0x01000193) >>> 0;
  return h;
};

export function AcceptanceStreamPage() {
  const api = usePluginApi();
  const [state, setState] = useState("waiting");
  useEffect(() => {
    let live = true;
    const stopAccept = api.streams.accept("down", (stream) => {
      void (async () => {
        let count = 0;
        let sum = 0x811c9dc5;
        const reader = stream.getReader();
        for (;;) {
          const r = await reader.read();
          if (r.done) break;
          count += r.value.length;
          sum = fnv(sum, r.value);
        }
        await api.host.call("pageReport", { kind: "down", count, sum });
        if (live) setState("down read");
      })().catch((e: unknown) => api.host.call("pageReport", { kind: "down", error: String(e instanceof Error ? e.message : e) }));
    });
    const stopUp = api.host.on("go-up", (data: unknown) => {
      const bytes = Number((data as { bytes?: number } | null)?.bytes ?? 0);
      void (async () => {
        const writer = (await api.streams.open("up", { meta: { bytes } })).getWriter();
        let sum = 0x811c9dc5;
        for (let at = 0; at < bytes; at += 100_000) {
          const piece = gen(2, at, Math.min(100_000, bytes - at));
          sum = fnv(sum, piece);
          await writer.write(piece);
        }
        await writer.close();
        await api.host.call("pageReport", { kind: "upSent", count: bytes, sum });
        if (live) setState("up sent");
      })().catch((e: unknown) => api.host.call("pageReport", { kind: "upSent", error: String(e instanceof Error ? e.message : e) }));
    });
    // Ready once its acceptor is registered (the daemon opens a stream to it only then) and its event listener is set.
    stopAccept.opened.then(() => api.host.call("pageReady", {})).then(() => live && setState("ready"), (e: unknown) => setState(`refused: ${String(e instanceof Error ? e.message : e).slice(0, 120)}`));
    return () => {
      live = false;
      stopAccept();
      stopUp();
    };
  }, [api]);
  return <span data-acceptance-stream-page="badge" data-state={state}>•</span>;
}
